161	fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
162	    workspace: &Workspace<'_, R, D>,
163	    selection: &ReleaseSelection,
164	    source: SourceIdentity,
165	) -> Result<(ReleaseInputSnapshotV1, Vec<ReleaseOperation>), GraphError> {
166	    let mut components = Vec::new();
167	    let mut kinds = BTreeSet::new();
168	
169	    // Raw config participates as bytes, not Debug formatting of internal
170	    // structs. The parser/resolver is still rebuilt above; this component
171	    // ensures formatting and every policy field influence authorization.
172	    let config_path = workspace.root.join("callisto.toml");
173	    let config = std::fs::read(&config_path).map_err(|error| GraphError::ReleaseInputRead {
174	        path: config_path,
175	        message: error.to_string(),
176	    })?;
177	    push_fingerprint(
178	        &mut components,
179	        &mut kinds,
180	        "config.callisto-toml",
181	        digest_bytes("config", &config),
182	    );
183	
184	    let mut selected = BTreeMap::new();
185	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
186	    for package in workspace.graph.packages() {
187	        for ecosystem in package
188	            .canonical_manifests()
189	            .map(|manifest| manifest.ecosystem())
190	            .collect::<BTreeSet<_>>()
191	        {
192	            let id = ReleasePackageId::new(ecosystem, package.id.name()).map_err(|_| GraphError::ReleaseIntentStale)?;
193	            if let Some(version) = selection.versions().get(&id) {
194	                selected.insert(id.clone(), (package, version.clone()));
195	                package_ids.entry(package.id.clone()).or_default().push(id);
196	            }
197	        }
198	    }
199	    for id in selection.versions().keys() {
200	        if !selected.contains_key(id) {
201	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
202	        }
203	    }
204	
205	    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
206	    let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
207	    let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();
208	
209	    // First construct leaves so dependency prerequisites can refer only to
210	    // exact selected release identities, never PackageId's wildcard matcher.
211	    for (id, (package, version)) in &selected {
212	        let fingerprint = package_fingerprint(workspace, id, package, version)?;
213	        push_fingerprint(&mut components, &mut kinds, format!("package:{id}"), fingerprint);
214	
215	        let mut publishes = Vec::new();
216	        for target in &package.publish_to {
217	            if target.ecosystem() == Some(id.ecosystem()) {
218	                let registry_key = target.registry_key().expect("registry target has registry key");
219	                let operation =
220	                    ReleaseOperation::registry_publish(id.clone(), version.clone(), registry_key.as_str(), Vec::new())
221	                        .map_err(|_| GraphError::ReleaseIntentStale)?;
222	                publishes.push(operation.id().clone());
223	                operations.insert(operation.id().clone(), operation);
224	            }
225	        }
226	        publishes.sort();
227	        publishes_by_package.insert(id.clone(), publishes);
228	    }
229	
230	    // Replace each publish leaf with prerequisites from selected dependency
231	    // packages. This preserves the existing publish semantics: runtime,
232	    // build, optional, and dev dependencies must exist before publish.
233	    for (id, (package, _)) in &selected {
234	        let mut prerequisites = BTreeSet::new();
235	        for edge in workspace.graph.dependencies_of(&package.id) {
236	            if !matches!(
237	                edge.kind,
238	                DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
239	            ) {
240	                continue;
241	            }
242	            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
243	                prerequisites.extend(
244	                    publishes_by_package
245	                        .get(dependency_release_id)
246	                        .into_iter()
247	                        .flatten()
248	                        .cloned(),
249	                );
250	            }
251	        }
252	        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
253	            let operation = operations.get(publish_id).expect("publish operation was constructed");
254	            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.iter().cloned().collect())
255	                .map_err(|_| GraphError::ReleaseIntentStale)?;
256	            operations.insert(publish_id.clone(), replacement);
257	        }
258	    }
259	
260	    for (id, (package, version)) in &selected {
261	        if !package
262	            .publish_to
263	            .iter()
264	            .any(|target| !matches!(target, PublishTarget::None))
265	        {
266	            continue;
267	        }
268	        let tag = ReleaseOperation::tag(
269	            id.clone(),
270	            version.clone(),
271	            publishes_by_package.get(id).cloned().unwrap_or_default(),
272	        )
273	        .map_err(|_| GraphError::ReleaseIntentStale)?;
274	        tag_by_package.insert(id.clone(), tag.id().clone());
275	        operations.insert(tag.id().clone(), tag);
276	    }
277	    for (id, (package, version)) in &selected {
278	        if package
279	            .publish_to
280	            .iter()
281	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
282	        {
283	            let tag = tag_by_package.get(id).expect("release point has tag").clone();
284	            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])
285	                .map_err(|_| GraphError::ReleaseIntentStale)?;
286	            operations.insert(operation.id().clone(), operation);
287	        }
288	    }
289	
290	    Ok((
291	        ReleaseInputSnapshotV1::new(source, components),
292	        canonical_operation_order(operations)?,
293	    ))
294	}
