 73	    /// Returns explicit, fresh Git trust evidence for a durable release.
 74	    /// Errors deliberately omit raw stderr and worktree path text.
 75	    pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
 76	        let root = self.runner.run("git", &["rev-parse", "--show-toplevel"], &self.root)?;
 77	        if !root.success() {
 78	            return Err(VcsError::Git(
 79	                "could not determine the Git repository root for release trust".to_string(),
 80	            ));
 81	        }
 82	        let canonical_root = canonical_git_root(root.stdout_trimmed())?;
 83	
 84	        let head = self
 85	            .runner
 86	            .run("git", &["rev-parse", "--verify", "HEAD^{commit}"], &self.root)?;
 87	        if !head.success() {
 88	            return Err(VcsError::Git(
 89	                "could not resolve a commit for release trust".to_string(),
 90	            ));
 91	        }
 92	        let head = CommitSha::parse(head.stdout_trimmed())
 93	            .map_err(|_| VcsError::Git("Git returned an invalid full HEAD commit for release trust".to_string()))?;
 94	
 95	        let symbolic_head = self
 96	            .runner
 97	            .run("git", &["symbolic-ref", "--quiet", "HEAD"], &self.root)?;
 98	        let head_disposition = match symbolic_head.exit_code {
 99	            Some(0) => GitHeadDisposition::Attached,
100	            Some(1) => GitHeadDisposition::Detached,
101	            _ => {
102	                return Err(VcsError::Git(
103	                    "could not determine the symbolic HEAD state for release trust".to_string(),
104	                ))
105	            }
106	        };
107	
108	        let status = self.runner.run(
109	            "git",
110	            &[
111	                "status",
112	                "--porcelain=v1",
113	                "-z",
114	                "--untracked-files=all",
115	                "--ignored=matching",
116	            ],
117	            &self.root,
118	        )?;
119	        if !status.success() {
120	            return Err(VcsError::Git(
121	                "could not inspect the worktree for release trust".to_string(),
122	            ));
123	        }
124	
125	        Ok(GitCommitTrustEvidence::new(
126	            canonical_root,
127	            head,
128	            head_disposition,
129	            parse_release_worktree_status(&status.stdout)?,
130	        ))
131	    }
132	}
