144	fn parse_release_worktree_status(status: &str) -> Result<Vec<PathBuf>, VcsError> {
145	    let mut allowed_ignored_paths = Vec::new();
146	    for record in status.split('\0').filter(|record| !record.is_empty()) {
147	        let Some(path) = record.strip_prefix("!! ") else {
148	            return Err(VcsError::Git(
149	                "release trust requires a worktree with no tracked or untracked files".to_string(),
150	            ));
151	        };
152	        let path = PathBuf::from(path);
153	        if !is_release_ignored_path_allowed(&path) {
154	            return Err(VcsError::Git(
155	                "release trust found an ignored path outside its fixed allowlist".to_string(),
156	            ));
157	        }
158	        allowed_ignored_paths.push(path);
159	    }
160	    allowed_ignored_paths.sort();
161	    allowed_ignored_paths.dedup();
162	    Ok(allowed_ignored_paths)
163	}
