134	fn canonical_git_root(raw_root: &str) -> Result<PathBuf, VcsError> {
135	    if raw_root.is_empty() {
136	        return Err(VcsError::Git(
137	            "Git returned an empty repository root for release trust".to_string(),
138	        ));
139	    }
140	    dunce::canonicalize(raw_root)
141	        .map_err(|_| VcsError::Git("could not canonicalize the Git repository root for release trust".to_string()))
