 93	pub fn validate_release_intent<L: ProjectLocator, R: CommandRunner>(
 94	    root: &Path,
 95	    locator: &L,
 96	    runner: &R,
 97	    selection: &ReleaseSelection,
 98	    received: ReleaseIntentV1,
 99	) -> Result<ValidatedReleaseIntent, GraphError> {
100	    let root = canonical_root(root)?;
101	    let workspace = Workspace::load(root.clone(), locator, runner)?;
102	    let source = observe_source(&workspace, received.trust_profile)?;
103	    let expected = derive_release_intent(&workspace, selection, source.clone(), received.trust_profile)?;
104	    if expected != received || observe_source(&workspace, received.trust_profile)? != source {
105	        return Err(GraphError::ReleaseIntentStale);
106	    }
107	
108	    Ok(ValidatedReleaseIntent {
109	        prepared: PreparedReleaseInputs {
110	            root,
111	            source,
112	            operation_ids: received
113	                .operations
114	                .iter()
115	                .map(|operation| operation.id().clone())
116	                .collect(),
117	        },
