129	fn observe_source<R: CommandRunner, D: DependencyResolver>(
130	    workspace: &Workspace<'_, R, D>,
131	    trust_profile: ExecutionTrustProfileV1,
132	) -> Result<SourceIdentity, GraphError> {
133	    match trust_profile {
134	        ExecutionTrustProfileV1::GitCommit => {
135	            let evidence = workspace.git_access().observe_git_commit_trust()?;
136	            if evidence.canonical_root() != workspace.root
137	                || evidence.head_disposition() != GitHeadDisposition::Detached
138	            {
139	                return Err(GraphError::ReleaseIntentStale);
140	            }
141	            Ok(SourceIdentity::GitCommit {
142	                sha: evidence.head().clone(),
143	            })
144	        }
145	        // No closed-root observer exists yet. Reject rather than claim Git
146	        // cleanliness proves a hermetic content identity.
147	        ExecutionTrustProfileV1::HermeticContent => Err(GraphError::ReleaseIntentStale),
148	    }
149	}
