 70	/// Builds a release intent from a fresh root-bound observation.
 71	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
 72	    root: &Path,
 73	    locator: &L,
 74	    runner: &R,
 75	    selection: &ReleaseSelection,
 76	    trust_profile: ExecutionTrustProfileV1,
 77	) -> Result<ReleaseIntentV1, GraphError> {
 78	    let root = canonical_root(root)?;
 79	    let workspace = Workspace::load(root.clone(), locator, runner)?;
 80	    let source = observe_source(&workspace, trust_profile)?;
 81	    let intent = derive_release_intent(&workspace, selection, source.clone(), trust_profile)?;
 82	
 83	    // Recheck after all input reads. A concurrent edit or checkout cannot be
 84	    // authorized merely because it happened after the first check.
 85	    if observe_source(&workspace, trust_profile)? != source {
 86	        return Err(GraphError::ReleaseIntentStale);
 87	    }
 88	    Ok(intent)
 89	}
