151	fn derive_release_intent<R: CommandRunner, D: DependencyResolver>(
152	    workspace: &Workspace<'_, R, D>,
153	    selection: &ReleaseSelection,
154	    source: SourceIdentity,
155	    trust_profile: ExecutionTrustProfileV1,
156	) -> Result<ReleaseIntentV1, GraphError> {
157	    let (snapshot, operations) = derive_release_inputs(workspace, selection, source)?;
158	    ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_| GraphError::ReleaseIntentStale)
159	}
