296	fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
297	    workspace: &Workspace<'_, R, D>,
298	    id: &ReleasePackageId,
299	    package: &callisto_model::Package,
300	    version: &Version,
301	) -> Result<SemanticInputDigest, GraphError> {
302	    let mut transcript = CanonicalTranscript::semantic_input_v1();
303	    transcript.push_str("package.id", &id.to_string());
304	    transcript.push_str("package.version", version.render());
305	    for manifest in &package.manifests {
306	        let path = workspace.root.join(&manifest.path);
307	        let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
308	            path: manifest.path.clone(),
309	            message: error.to_string(),
310	        })?;
311	        transcript.push_str("manifest.path", &manifest.path.display().to_string());
312	        transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
313	        transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
314	        transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
315	    }
316	    transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
317	    transcript.push_str(
318	        "package.tag",
319	        &package
320	            .tag_template
321	            .as_ref()
322	            .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
323	    );
324	    for target in &package.publish_to {
325	        transcript.push_str("package.target", target_fingerprint(target)?.as_str());
326	    }
327	    Ok(SemanticInputDigest::from_transcript(&transcript))
328	}
